import{_ as l,C as o,o as d,c,a6 as s,E as a,j as t,a as i}from"./chunks/framework.5dd0l9Wo.js";const k=JSON.parse('{"title":"Web LLM Attacks","description":"Prompt injection, excessive agency, tool abuse, insecure output handling, and data exfiltration through AI features.","frontmatter":{"title":"Web LLM Attacks","description":"Prompt injection, excessive agency, tool abuse, insecure output handling, and data exfiltration through AI features."},"headers":[],"relativePath":"llm/index.md","filePath":"llm/index.md"}'),u={name:"llm/index.md"};function m(p,e,h,g,b,f){const n=o("LabGroup"),r=o("TopicComplete");return d(),c("div",null,[e[0]||(e[0]=s('<h1 id="web-llm-attacks" tabindex="-1">Web LLM Attacks <a class="header-anchor" href="#web-llm-attacks" aria-label="Permalink to &quot;Web LLM Attacks&quot;">​</a></h1><p class="wd-section-lede">An LLM feature is a confused deputy with a natural-language interface. It reads instructions and data through the same channel, and it may have tools that can read files, call APIs, or send email. The attack is not &quot;jailbreaking the model&quot; — it is making the application do something its tools allow but its policy forbids.</p><div class="wd-callout"><p><strong>The model.</strong> Treat the model as an untrusted user of your tools. Instructions can arrive directly from the attacker or indirectly through any content the model ingests (a web page, an email, a file). The security boundary is the tool permissions and output handling, not the prompt.</p></div><h2 id="direct-and-indirect-prompt-injection" tabindex="-1">Direct and indirect prompt injection <a class="header-anchor" href="#direct-and-indirect-prompt-injection" aria-label="Permalink to &quot;Direct and indirect prompt injection&quot;">​</a></h2><ul><li><strong>Direct:</strong> the attacker types the instruction into the chat.</li><li><strong>Indirect:</strong> the instruction is embedded in content the model reads — a product review, a support ticket, a web page it is asked to summarise.</li></ul><p>Indirect injection is the dangerous one because the victim triggers it by using a normal feature.</p>',6)),a(n,{ids:"llm-lab-indirect-prompt-injection, llm-lab-indirect-prompt-injection-via-ai-powered-scan"}),e[1]||(e[1]=t("h2",{id:"excessive-agency",tabindex:"-1"},[i("Excessive agency "),t("a",{class:"header-anchor",href:"#excessive-agency","aria-label":'Permalink to "Excessive agency"'},"​")],-1)),e[2]||(e[2]=t("p",null,"Every tool the model can call is an action an attacker may be able to trigger. Enumerate the tools: user lookup, password reset, file read, HTTP request, email, database query. Then ask what the model is allowed to do with them without human confirmation.",-1)),a(n,{ids:"llm-lab-exploiting-llm-apis-with-excessive-agency, llm-lab-exploiting-vulnerabilities-in-llm-apis"}),e[3]||(e[3]=t("details",{class:"details custom-block"},[t("summary",null,"🔬 Under the Hood: why prompt filtering fails"),t("p",null,'A prompt is natural language; there is no grammar that separates instruction from data. Filters that block "ignore previous instructions" are defeated by paraphrase, encoding, translation, or by putting the instruction in a tool result. The model has no reliable notion of "this text is data, not a command" unless the application enforces it structurally.'),t("p",null,"Mitigations are architectural: least-privilege tools, human confirmation for destructive actions, allow-lists for URLs and commands, and output encoding.")],-1)),e[4]||(e[4]=t("h2",{id:"insecure-output-handling",tabindex:"-1"},[i("Insecure output handling "),t("a",{class:"header-anchor",href:"#insecure-output-handling","aria-label":'Permalink to "Insecure output handling"'},"​")],-1)),e[5]||(e[5]=t("p",null,[i("Model output is untrusted input to whatever consumes it. If the chat renders Markdown as HTML, a response containing "),t("code",null,"<img src=x onerror=...>"),i(" becomes XSS. If the output is passed to a shell, it becomes command injection. If it is used as a URL, it becomes SSRF.")],-1)),a(n,{ids:"llm-lab-exploiting-insecure-output-handling-in-llms"}),e[6]||(e[6]=t("h2",{id:"data-exfiltration",tabindex:"-1"},[i("Data exfiltration "),t("a",{class:"header-anchor",href:"#data-exfiltration","aria-label":'Permalink to "Data exfiltration"'},"​")],-1)),e[7]||(e[7]=t("p",null,"A model with access to sensitive data and an outbound channel can be instructed to send that data to an attacker. The channel may be a markdown image, a link the user clicks, or a tool call. Blocking the obvious channel is not enough; the model may find another.",-1)),a(n,{ids:"llm-lab-sensitive-information-exfiltration, llm-lab-bypassing-ai-scanner-defenses-to-exfiltrate-sensitive-information"}),e[8]||(e[8]=t("h2",{id:"chaining-into-classic-vulnerabilities",tabindex:"-1"},[i("Chaining into classic vulnerabilities "),t("a",{class:"header-anchor",href:"#chaining-into-classic-vulnerabilities","aria-label":'Permalink to "Chaining into classic vulnerabilities"'},"​")],-1)),e[9]||(e[9]=t("p",null,"An AI agent that can browse or call internal APIs can be pointed at SSRF, XSS, or command injection sinks. The LLM is the delivery mechanism; the underlying bug is the same as in the server-side modules.",-1)),a(n,{ids:"llm-lab-exploiting-target-website-vulnerabilities-to-bypass-restrictions"}),e[10]||(e[10]=s('<details class="details custom-block"><summary>⚙️ Engine Variations: tool-calling implementations</summary><ul><li><strong>OpenAI function calling:</strong> the model returns a JSON tool call; the application executes it.</li><li><strong>LangChain agents:</strong> tools are Python functions; the agent chooses among them.</li><li><strong>MCP servers:</strong> tools are exposed over a protocol; permissions are per server.</li><li><strong>RAG pipelines:</strong> retrieved documents are inserted into the prompt, making them an indirect injection vector.</li><li><strong>Browser agents:</strong> the model can navigate and click; the web page is both data and instruction.</li></ul><p>The implementation decides whether the model&#39;s output is validated before a tool runs.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Give the model the minimum tool set with the minimum permissions. Require human confirmation for destructive or external actions. Validate tool arguments against strict schemas and allow-lists. Encode model output for its destination context. Do not put secrets in the prompt or in data the model can read. Treat retrieved content as untrusted. Log every tool call for audit.</p></div>',2)),a(r,{"topic-id":"web-llm-attacks",label:"Mark LLM attacks complete"})])}const x=l(u,[["render",m]]);export{k as __pageData,x as default};
